-- virtualCrypto baseline schema (Milestone 1).
--
-- Generated by scripts/generate-baseline.py from `pg_dump --schema-only`
-- of an empty database migrated with the Ecto migrations. Every statement
-- is idempotent so this applies cleanly both to a fresh database and to the
-- existing production database, where the objects already exist.
--
-- Do not edit by hand: regenerate instead.

DO $baseline$
BEGIN
CREATE TYPE public.openid_connect_application_type AS ENUM (
    'native',
    'web'
);
EXCEPTION WHEN duplicate_object THEN NULL;
END
$baseline$;;

