$baseline$;;

CREATE OR REPLACE FUNCTION public.claim_metadata_remove_row() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  DELETE FROM claim_metadata WHERE id=NEW.id;
  RETURN NULL;
END;
$$;

CREATE OR REPLACE FUNCTION public.claim_metadata_strip_nulls() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
    UPDATE claim_metadata SET metadata=jsonb_strip_nulls(NEW.metadata) WHERE id=NEW.id;
    RETURN NULL;
  END;
$$;

CREATE OR REPLACE FUNCTION public.delete_asset_by_id() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
    DELETE FROM assets WHERE assets.id = NEW.id;
    RETURN NULL;
  END;
$$;

CREATE OR REPLACE FUNCTION public.metadata_limitation(json_obj jsonb) RETURNS boolean
    LANGUAGE plpgsql
    AS $$
DECLARE
entry RECORD;
key_count INTEGER;
BEGIN
  key_count := 0;
  FOR entry IN (
    SELECT * FROM jsonb_each(json_obj)
  )
  LOOP
    key_count := key_count + 1;
    IF length(entry.key::text) > 40 OR jsonb_typeof(entry.value) != 'string' OR length(entry.value#>>'{}') > 500 OR key_count > 50 THEN
      RETURN FALSE;
    END IF;
  END LOOP;
  RETURN TRUE;
END;
$$;

CREATE OR REPLACE FUNCTION public.metadata_limitation_trigger() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
  BEGIN
    RAISE check_violation;
  END;
$$;

CREATE TABLE IF NOT EXISTS public.access_tokens (
    id bigint NOT NULL,
    grant_id bigint,
    expires timestamp(0) without time zone,
    inserted_at timestamp(0) without time zone NOT NULL,
    updated_at timestamp(0) without time zone NOT NULL,
    token_id uuid
);

CREATE SEQUENCE IF NOT EXISTS public.access_tokens_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.access_tokens_id_seq OWNED BY public.access_tokens.id;

CREATE TABLE IF NOT EXISTS public.applications (
    id bigint NOT NULL,
    status integer,
    client_id uuid,
    client_secret character varying(255),
    response_types public.openid_connect_response_types[] DEFAULT ARRAY['code'::public.openid_connect_response_types],
    grant_types public.openid_connect_grant_types[] DEFAULT ARRAY['authorization_code'::public.openid_connect_grant_types],
    application_type public.openid_connect_application_type DEFAULT 'web'::public.openid_connect_application_type,
    client_name character varying(255),
    client_uri character varying(255),
    logo_uri character varying(255),
    owner_discord_id bigint,
    discord_support_server_invite_slug character varying(255),
    inserted_at timestamp(0) without time zone NOT NULL,
    updated_at timestamp(0) without time zone NOT NULL,
    webhook_url character varying(2048),
    public_key bytea NOT NULL,
    private_key bytea NOT NULL
);

CREATE SEQUENCE IF NOT EXISTS public.applications_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.applications_id_seq OWNED BY public.applications.id;

CREATE TABLE IF NOT EXISTS public.assets (
    id bigint NOT NULL,
    amount bigint,
    user_id bigint,
    currency_id bigint,
    inserted_at timestamp(0) without time zone NOT NULL,
    updated_at timestamp(0) without time zone NOT NULL,
    CONSTRAINT amount_must_be_positive CHECK ((amount > 0))
);

CREATE SEQUENCE IF NOT EXISTS public.assets_id_seq
    START WITH 1
    INCREMENT BY 1
    NO MINVALUE
    NO MAXVALUE
    CACHE 1;

ALTER SEQUENCE public.assets_id_seq OWNED BY public.assets.id;

CREATE TABLE IF NOT EXISTS public.authorization_codes (
