CREATE UNIQUE INDEX IF NOT EXISTS refresh_tokens_grant_id_index ON public.refresh_tokens USING btree (grant_id);

CREATE UNIQUE INDEX IF NOT EXISTS refresh_tokens_id_index ON public.refresh_tokens USING btree (id);

CREATE UNIQUE INDEX IF NOT EXISTS refresh_tokens_token_id_index ON public.refresh_tokens USING btree (token_id);

CREATE UNIQUE INDEX IF NOT EXISTS text_claims_id ON public.claims USING btree (((id)::text));

CREATE INDEX IF NOT EXISTS user_access_tokens_expires_index ON public.user_access_tokens USING btree (expires);

CREATE UNIQUE INDEX IF NOT EXISTS user_access_tokens_token_id_index ON public.user_access_tokens USING btree (token_id);

CREATE INDEX IF NOT EXISTS user_access_tokens_user_id_index ON public.user_access_tokens USING btree (user_id);

CREATE UNIQUE INDEX IF NOT EXISTS users_application_id_index ON public.users USING btree (application_id);

CREATE UNIQUE INDEX IF NOT EXISTS users_discord_id_index ON public.users USING btree (discord_id);

CREATE UNIQUE INDEX IF NOT EXISTS users_id_index ON public.users USING btree (id);

DROP TRIGGER IF EXISTS _remove_entry_if_empty ON public.claim_metadata;
CREATE TRIGGER _remove_entry_if_empty BEFORE UPDATE OF metadata ON public.claim_metadata FOR EACH ROW WHEN (('{}'::jsonb @> new.metadata)) EXECUTE FUNCTION public.claim_metadata_remove_row();

DROP TRIGGER IF EXISTS delete_asset_when_amount_is_zero ON public.assets;
CREATE TRIGGER delete_asset_when_amount_is_zero BEFORE INSERT OR UPDATE OF amount ON public.assets FOR EACH ROW WHEN ((new.amount = 0)) EXECUTE FUNCTION public.delete_asset_by_id();

DROP TRIGGER IF EXISTS metadata_limitation ON public.claim_metadata;
CREATE TRIGGER metadata_limitation BEFORE UPDATE OF metadata ON public.claim_metadata FOR EACH ROW WHEN ((NOT public.metadata_limitation(new.metadata))) EXECUTE FUNCTION public.metadata_limitation_trigger();

DROP TRIGGER IF EXISTS strip_nulls_after_insert ON public.claim_metadata;
CREATE TRIGGER strip_nulls_after_insert AFTER INSERT ON public.claim_metadata FOR EACH ROW EXECUTE FUNCTION public.claim_metadata_strip_nulls();

DO $baseline$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'access_tokens_grant_id_fkey'
      AND conrelid = 'public.access_tokens'::regclass) THEN
    ALTER TABLE ONLY public.access_tokens
    ADD CONSTRAINT access_tokens_grant_id_fkey FOREIGN KEY (grant_id) REFERENCES public.grants(id) ON UPDATE CASCADE ON DELETE CASCADE;
  END IF;
END
$baseline$;;

